  Object.defineProperty(missing,'push',{value:(...items) => { postMessage({progress:'missing',items}); return Array.prototype.push.apply(missing,items); }});
  let stdout = '', stderr = '', finished = false;
  const finish = result => { if (!finished) { finished = true; postMessage({done:true, ...result, stdout, stderr, trace, missing, requests}); } };
  self.addEventListener('error', e => { if (!finished) finish({error: e.message}); e.preventDefault(); });
  self.addEventListener('unhandledrejection', e => { if (!finished) finish({error: String(e.reason?.stack ?? e.reason)}); e.preventDefault(); });
  const get = async url => { requests.push(url); const r = await fetch(url); if (!r.ok) throw Error(url + ': ' + r.status); return r; };
  try {
    const manifest = await (await get('/dynamic-e-profile.manifest.json')).json();
    const expected = new Map(manifest.files.map(f => [f.path, f]));
    const contents = new Map(), root = new shim.Directory(contents);
    function put(name, data) {
      const parts = name.split('/'); let dir = root;
      for (const part of parts.slice(0, -1)) { if (!dir.contents.has(part)) dir.contents.set(part, new shim.Directory(new Map())); dir = dir.contents.get(part); }
      dir.contents.set(parts.at(-1), new shim.File(data.buffer, {readonly: true}));
    }
    let pending = new Uint8Array(), entry, left = 0, padding = 0, chunks = [], total = 0;
    const reader = (await get('/dynamic-e-profile.tar.gz.bin')).body.pipeThrough(new DecompressionStream('gzip')).getReader();
    for (;;) {
      const {done, value} = await reader.read(); if (done) break;
      const joined = new Uint8Array(pending.length + value.length); joined.set(pending); joined.set(value, pending.length); pending = joined;
      for (;;) {
        if (left) {
          const n = Math.min(left, pending.length); chunks.push(pending.slice(0,n)); pending = pending.subarray(n); left -= n;
          if (left) break;
          const bytes = new Uint8Array(entry.bytes); let at = 0; for (const c of chunks) { bytes.set(c, at); at += c.length; } chunks = [];
