    for (const name of ['findSystemLibrary','addLibrarySearchPath','fetchWasm']) { const fn = rpc[name].bind(rpc); rpc[name] = async (...args) => { trace.push({name,args}); try { const result = await fn(...args); if (typeof result === 'string') trace.push({name,result}); return result; } catch (err) { trace.push({name,error:String(err)}); throw err; } }; }
