    if (request.infoOnly) args.splice(0,args.length,'ghc','-B/ghc','--info');
    if (request.verbose) args[2]='-v3';
    if (request.dynamic) args.splice(1,0,'-dynamic');
    if (request.bareEval) args.splice(0,args.length,'ghc','-B/ghc','-e','1+1');
    if (request.showPackages) args.splice(0,args.length,'ghc','-B/ghc','--show-packages');
