    Object.assign(exports, instance.exports);
    postMessage({progress:'starting',args,identity:{ghc:manifest.ghcSha256,profile:manifest.archiveSha256},payloadBytes:total});
    const returned = wasi.start(instance);
    postMessage({progress:'start-returned', returned});
  } catch (error) { finish({error:String(error.stack ?? error)}); }
};

